sources.content:
#include <Servo.h>
Servo arm;

void setup() {
  arm.attach(9);  // the servo's signal wire is on D9
}

void loop() {
  for (int a = 0; a <= 180; a++) {
    arm.write(a);  // turn to this angle, 0-180°
    delay(12);
  }
  for (int a = 180; a >= 0; a--) {
    arm.write(a);
    delay(12);
  }
}
